"""docich#5452 — a battle during destination steering kills the いどう mode.

A defense battle that interrupts the recall's destination picker ('dest',
'y_route', 'relay', 'hero_focus', 'hero_open') destroys the いどう move
mode along with the foreground, but the old resume logic treated the first
post-battle 'map' as the live いどう field cursor. The Y route then opened
the whole map in *view* mode, where an A on an own castle opens castle_menu
instead of naming the destination — the confirm A landed in that menu, the
return never launched, and the unconfirmed terminal was counted as a
(camp, castle) refusal (camp_recall_goal_failed).

The fix: MOVE_MODE_STAGES take the battle_return marker; a post-battle 'map'
or menu/panel screen restarts the recall from scratch
(_recall_move_mode_lost, a short interrupted-dispatch hold) instead of
resuming the Y route; a surviving 'map_target' picker gets its stale jump
receipts dropped like observe_sortie_transition does; and the dispatch
terminal records the screens it saw so a mode-loss ending (castle_menu et
al.) is never counted as a destination refusal.
"""
import pytest
from types import SimpleNamespace

from docich.hanjuku_speedrun.hanjuku.flows import recall as recall_flow
from docich.hanjuku_speedrun.hanjuku.flows import map as map_flow
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import Screen
from docich.hanjuku_speedrun.hanjuku.state.regions import flow as _flow


BATTLE = Screen([], None, '', kind='battle')
MAP = Screen([], None, '', kind='map', cursor=(80, 90))


def memory(stage='dest', tick=100, **recall):
    mem = {'chapter': 1, 'tick': tick, '_records': [],
           'captured': ['キカンドン', 'ジョンリギ', 'ゴーメン']}
    _flow(mem)['recall'] = {'stage': stage, 'steps': 1, 'target': [139, 113],
                            **recall}
    return mem


@pytest.mark.parametrize('stage', recall_flow.MOVE_MODE_STAGES)
def test_a_battle_during_destination_steering_marks_battle_return(stage):
    mem = memory(stage=stage)
    assert recall_flow.camp_recall_step(BATTLE, mem, None) is None
    assert _flow(mem)['recall']['battle_return'] is True


@pytest.mark.parametrize('stage', recall_flow.MOVE_MODE_STAGES)
def test_a_post_battle_map_never_resumes_the_move_mode(stage):
    """The incident: dest resumed Y on a plain post-battle field, opened a
    view-mode world map and sent its confirm A into castle_menu. The first
    post-battle 'map' must instead restart the recall — no Y, no A."""
    mem = memory(stage=stage, goal='キカンドン')
    recall_flow.camp_recall_step(BATTLE, mem, None)
    actions = recall_flow.camp_recall_step(MAP, mem, None)
    assert actions == []
    assert not _flow(mem).get('recall')
    assert 'y_jump' not in mem
    assert mem['uncertain'] is True
    interrupted = [r for r in mem['_records']
                   if r['decision'] == 'camp_recall_interrupted']
    assert interrupted and interrupted[0]['resulting_event'] == 'move_mode_lost'
    assert interrupted[0]['observed_metric']['stage'] == stage
    assert _flow(mem)['recall_skip_ticks'] == recall_flow.FORT_RETRY_TICKS
    assert not any(r['decision'] == 'camp_recall_y_route' for r in mem['_records'])


def test_a_post_battle_map_drops_the_recalls_own_in_flight_jump():
    mem = memory(stage='y_route', goal='キカンドン')
    mem['y_jump'] = {'step': 'RECALL', 'goal': 'キカンドン', 'target': 'target'}
    mem['y_jumped'] = {'RECALL': 'キカンドン'}
    recall_flow.camp_recall_step(BATTLE, mem, None)
    assert recall_flow.camp_recall_step(MAP, mem, None) == []
    assert 'y_jump' not in mem
    assert 'RECALL' not in mem['y_jumped']
    assert not _flow(mem).get('recall')


def test_a_surviving_picker_after_battle_re_drives_from_cleared_receipts(monkeypatch):
    """If the picker itself survived (map_target), a fresh jump re-places the
    marker — the stale receipt must not blind-confirm (sortie's mechanism)."""
    monkeypatch.setattr(recall_flow, 'castle_roofs', lambda *_a, **_k: [])
    mem = memory(stage='dest', goal='キカンドン', picker_confirmed=True)
    mem['y_jumped'] = {'RECALL': 'キカンドン'}
    mem['y_jumps'] = {'RECALL:target': 2}
    recall_flow.camp_recall_step(BATTLE, mem, None)
    screen = Screen([], None, '', kind='map_target', marker=(90, 80))
    from docich.hanjuku_speedrun.hanjuku.os_layer.commands import pad
    assert recall_flow.camp_recall_step(screen, mem, None) == [pad('y')]
    state = _flow(mem)['recall']
    assert state is not None and state['stage'] == 'dest'
    assert 'battle_return' not in state
    assert mem['y_jump']['step'] == 'RECALL'
    assert mem['y_jumps']['RECALL:target'] == 1     # a fresh count, not 2


def test_a_castle_menu_during_destination_steering_is_mode_loss():
    """Only a mis-fired own input can open castle_menu while the recall steers
    a destination — never steer inside it; close it and restart."""
    mem = memory(stage='dest', goal='キカンドン')
    screen = Screen([], None, '', kind='castle_menu')
    from docich.hanjuku_speedrun.hanjuku.os_layer.commands import pad
    assert recall_flow._camp_recall_step(screen, mem, None) == [pad('b')]
    assert not _flow(mem).get('recall')
    assert any(r['decision'] == 'camp_recall_interrupted'
               and r['resulting_event'] == 'move_mode_lost'
               for r in mem['_records'])


