def test_a_world_map_after_battle_is_mode_loss():
    """world_map_step owns world_map screens; the same post-battle guard must
    fire there too so the view's A never opens castle_menu."""
    mem = memory(stage='dest', goal='キカンドン')
    recall_flow.camp_recall_step(BATTLE, mem, None)
    mem['y_jump'] = {'step': 'RECALL', 'goal': 'キカンドン'}
    screen = Screen([], None, '', kind='world_map')
    from docich.hanjuku_speedrun.hanjuku.os_layer.commands import pad
    assert map_flow.world_map_step(screen, mem, None) == [pad('b')]
    assert 'y_jump' not in mem
    assert not _flow(mem).get('recall')
    assert any(r['decision'] == 'camp_recall_interrupted'
               and r['resulting_event'] == 'move_mode_lost'
               for r in mem['_records'])


def _dispatch_state(**extra):
    return {'stage': 'await_dispatch', 'steps': 0, 'goal': 'カルーン',
            'target': [139, 113], 'input_sent': True, **extra}


def test_a_castle_menu_terminal_is_mode_loss_not_a_pair_refusal():
    """The incident's terminal: 6 castle_menu observations, input_sent, no
    picker close. arrival_unconfirmed is kept, but the (camp, castle) pair
    must not be counted as refused."""
    state = _dispatch_state()
    mem = {'chapter': 5, 'tick': 100, '_records': [], 'flow': {'recall': state}}
    screen = SimpleNamespace(kind='castle_menu')
    actions = None
    for _ in range(6):
        actions = recall_flow._recall_dispatch_step(screen, mem, state)
    from docich.hanjuku_speedrun.hanjuku.os_layer.commands import pad
    assert actions == [pad('b')]
    assert 'recall' not in mem['flow']
    verification = mem['flow']['recall_verification']
    assert verification['status'] == 'arrival_unconfirmed'
    assert verification['interrupted'] is True        # mode loss is interruption-like
    assert not _flow(mem).get('recall_goal_failures')
    assert not any(r['decision'] == 'camp_recall_goal_failed' for r in mem['_records'])
    mode_lost = [r for r in mem['_records'] if r['decision'] == 'camp_recall_mode_lost']
    assert mode_lost and mode_lost[0]['resulting_event'] == 'move_mode_lost'
    unconfirmed = [r for r in mem['_records'] if r['decision'] == 'camp_recall_unconfirmed']
    assert unconfirmed
    assert unconfirmed[0]['observed_metric']['mode_lost'] is True
    assert 'castle_menu' in unconfirmed[0]['observed_metric']['recent_screens']
    assert _flow(mem)['recall_skip_ticks'] == recall_flow.FORT_RETRY_TICKS


def test_an_ordinary_unconfirmed_terminal_still_counts_the_pair():
    """picker screens are not foreign: the old refusal counting stays."""
    state = _dispatch_state()
    mem = {'chapter': 5, 'tick': 100, '_records': [], 'flow': {'recall': state}}
    screen = SimpleNamespace(kind='map_target')
    for _ in range(6):
        recall_flow._recall_dispatch_step(screen, mem, state)
    assert (_flow(mem).get('recall_goal_failures') or {}).get('139,113') == {'カルーン': 1}
    assert any(r['decision'] == 'camp_recall_goal_failed' for r in mem['_records'])
    unconfirmed = [r for r in mem['_records'] if r['decision'] == 'camp_recall_unconfirmed']
    assert unconfirmed and unconfirmed[0]['observed_metric']['mode_lost'] is False


def test_a_to_camp_battle_return_still_restarts_only_the_budget():
    """The field-navigation stages keep their #5134 cursor-budget restart —
    mode loss applies only to destination steering."""
    mem = memory(stage='to_camp')
    state = _flow(mem)['recall']
    state['steps'] = 90
    assert recall_flow.camp_recall_step(BATTLE, mem, None) is None
    assert state['battle_return'] is True
    recall_flow.camp_recall_step(MAP, mem, None)
    assert state['battle_resets'] == 1 and 'battle_return' not in state
    assert state['steps'] == 1                        # restarted, not aborted
    assert _flow(mem).get('recall')
